/// Registered spec for `hydraulics.reynolds_number`.
///
/// Public and addressable directly, so a calc can hold `&REYNOLDS_NUMBER_SPEC` with no
/// lookup and no failure path. A calc whose spec is missing is a build-time
/// invariant, not a runtime condition, and this shape makes it unrepresentable
/// rather than something to handle.
pub static REYNOLDS_NUMBER_SPEC: CalcSpec = CalcSpec {
    id: "hydraulics.reynolds_number",
    verification: "unverified",
    checks: REYNOLDS_NUMBER_CHECKS,
    solver: None,
    worked_example: TestCase {
        id: "water_pipe_worked_example",
        kind: "worked_example",
        property: None,
        status: "active",
        skip_reason: None,
        tolerance: 1e-12,
        numbers: &[("rho", 998.0), ("v", 1.5), ("D", 0.1), ("mu", 0.001002)],
        lists: &[],
        expected: &[("re", 149401.19760479042)],
    },
    tests: REYNOLDS_NUMBER_TESTS,
};

/// Every calculation in the registry, sorted by id.
static ALL_SPECS: &[&CalcSpec] = &[
    &CRANE_K_FACTORS_SPEC,
    &DARCY_WEISBACH_SPEC,
    &FRICTION_FACTOR_COLEBROOK_SPEC,
    &FRICTION_FACTOR_HAALAND_SPEC,
    &FRICTION_FACTOR_SWAMEE_JAIN_SPEC,
    &REYNOLDS_NUMBER_SPEC,
];

/// All specs, in a stable order.
#[must_use]
pub fn specs() -> &'static [&'static CalcSpec] {
    ALL_SPECS
}

/// Look up a spec by id.
#[must_use]
pub fn spec(id: &str) -> Option<&'static CalcSpec> {
    ALL_SPECS.iter().copied().find(|s| s.id == id)
}
